  "summary": "The code contained critical security vulnerabilities due to hardcoded credentials and performance bottlenecks from synchronous connection handling. The refactored version implements environment variable injection, secure TLS context management, and improved code documentation/typing.",
  "fixed_code": "import smtplib\nimport os\nimport ssl\nfrom email.message import EmailMessage\nfrom typing import Dict, Any\n\n# Configuration retrieved from environment variables\nSMTP_CONFIG = {\n    \"host\": os.environ.get(\"SMTP_HOST\", \"mail.example.com\"),\n    \"port\": int(os.environ.get(\"SMTP_PORT\", 587)),\n    \"username\": os.environ.get(\"SMTP_USER\"),\n    \"password\": os.environ.get(\"SMTP_PASSWORD\"),\n}\n\ndef send_email(to: str, subject: str, body: str, config: Dict[str, Any] = SMTP_CONFIG) -> None:\n    \"\"\"Sends an email using the configured SMTP server with TLS security.\"\"\"\n    if not to or \"@\" not in to:\n        raise ValueError(\"Invalid recipient email address.\")\n\n    msg = EmailMessage()\n    msg[\"From\"], msg[\"To\"], msg[\"Subject\"] = config[\"username\"], to, subject\n    msg.set_content(body)\n\n    context = ssl.create_default_context()\n    with smtplib.SMTP(config[\"host\"], config[\"port\"]) as smtp:\n        smtp.starttls(context=context)\n        smtp.login(config[\"username\"], config[\"password\"])\n        smtp.send_message(msg)"
